const VIDEO_ROOT=new URL('./video/',import.meta.url);
export class BannerScene{
 constructor(container,{motion=true,onError=()=>{},onState=()=>{}}={}){
  Object.assign(this,{container,onError,onState,wantedMotion:!!motion,motion:false,visible:true,zoom:1,disposed:false,playToken:0});
  const video=this.video=document.createElement('video');video.className='banner-video';video.muted=true;video.defaultMuted=true;video.loop=true;video.playsInline=true;video.autoplay=!!motion;video.preload=motion?'auto':'metadata';video.poster=new URL('black-hole.webp',VIDEO_ROOT).href;video.setAttribute('muted','');video.setAttribute('playsinline','');video.setAttribute('loop','');video.setAttribute('aria-label','Video hố đen và đĩa bồi tụ. Nguồn NASA. Dùng nút Phát video hoặc Tạm dừng video để điều khiển.');
  for(const [file,type]of [['black-hole.webm','video/webm'],['black-hole.mp4','video/mp4']]){const source=document.createElement('source');source.src=new URL(file,VIDEO_ROOT).href;source.type=type;video.append(source);}
  this.events=[['playing',()=>{this.motion=true;this.blocked=false;this.failed=false;this.notify();}],['pause',()=>{this.motion=false;this.notify();}],['loadedmetadata',()=>this.notify()],['error',()=>{this.failed=true;this.motion=false;this.notify();this.onError(Error('Không tải được video NASA'));}]];for(const [name,fn]of this.events)video.addEventListener(name,fn);
  container.replaceChildren(video);this.onVisibility=()=>this.reconcile();document.addEventListener('visibilitychange',this.onVisibility);this.intersection=globalThis.IntersectionObserver?new IntersectionObserver(entries=>{this.visible=!!entries[0]?.isIntersecting;this.reconcile();}):null;this.intersection?.observe(container);this.reconcile();
 }
 notify(){if(this.disposed)return;const info=document.querySelector('#bannerResolutionInfo');if(info)info.textContent=this.video.videoWidth?`${this.video.videoWidth} × ${this.video.videoHeight} · Video`:'Full HD · Video NASA';const button=document.querySelector('[data-action="banner-motion"]');if(button){button.textContent=this.motion?'Tạm dừng video':this.failed?'Thử lại video':'Phát video';button.setAttribute('aria-pressed',String(this.motion));}const status=document.querySelector('#bannerStatus');if(status)status.textContent=this.failed?'Chưa tải được video · nhấn Thử lại video':this.blocked?'Trình duyệt đang chặn tự phát · nhấn Phát video':'NASA / Jeremy Schnittman · Hình dựng mô phỏng';this.onState({playing:this.motion,blocked:!!this.blocked,failed:!!this.failed});}
 async reconcile(){const token=++this.playToken;if(this.disposed)return;if(!this.wantedMotion||!this.visible||document.hidden){this.video.pause();this.motion=false;this.notify();return;}try{await this.video.play();if(this.disposed||token!==this.playToken)return;this.motion=!this.video.paused;this.blocked=false;}catch{if(this.disposed||token!==this.playToken)return;this.motion=false;this.blocked=true;}this.notify();}
 async setMotion(value){this.wantedMotion=!!value;if(value&&this.failed){this.failed=false;this.video.load();}return this.reconcile();}
 setSpread(value){this.zoom=1+Math.max(0,Math.min(1,Number(value)||0))*.25;this.video.style.transform=`scale(${this.zoom})`;}
 setScroll(){}
 setQuality(){}
 resize(){}
 dispose(){if(this.disposed)return;this.disposed=true;++this.playToken;this.intersection?.disconnect();document.removeEventListener('visibilitychange',this.onVisibility);for(const [name,fn]of this.events)this.video.removeEventListener(name,fn);this.video.pause();this.video.removeAttribute('src');this.video.querySelectorAll('source').forEach(s=>s.removeAttribute('src'));this.video.load();}
}
